#' @export
jrReportTTestIS <- function(data) {
    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("jrReportTTestIS requires jmvcore to be installed (restart may be required)")
    if (missing(data))
        data <- jmvcore::marshalData(parent.frame())
    options <- jrReportTTestISOptions$new()
    analysis <- jrReportTTestISClass$new(options = options, data = data)
    analysis$run()
    analysis$results
}

